"""Original whale action guides, fixed anatomical registration and grounded corpse."""
import json
import produce as p
UID='unit_neutral_saltwake_bellwhales'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original SALTWAKE BELLWHALE from the supplied painting, hover-swimming SCREEN RIGHT. One dark navy whale body with pale ivory/turquoise ventral throat plates, original turquoise eye and small crystalline dorsal ridge. Exactly TWO teal pectoral fins: broad near fin flowing left/down and far fin beneath the jaw flowing right/down. ONE tail peduncle ending in exactly TWO frilled teal tail flukes. The original gold-edged translucent fin membranes, gold filigree bronze harness, THREE principal bronze underbelly bells and TWO small tail-base bells with blue clappers remain attached by their original fine chains. No extra fins, tails, bells, legs, arms, hands, weapons, horns or human anatomy. Painted fantasy game artwork, same body size and camera. ')
PLATE=(' Entire backdrop flat magenta RGB255,0,255 throughout, no scenery, water, floor, cast shadow, text, camera movement, zoom or cuts. Keep all fin and fluke tips, chains and bells inside generous canvas margins. Fixed world ground plane y576; living whale hovers above this plane and only the death ends with its body resting on it. Keep original pale throat plates and translucent teal fins without recoloring, swelling or dissolving anatomy. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if index<16:
  # One master-wide horizontal/vertical registration from the near-fin joint,
  # not per-frame bounding boxes: old ready joint(230,177), accepted idle(245,312).
  # Original scales .8/.7322 give common joint offset(+38.8,-93.7) runtime pixels.
  f['anchor']=[f['anchor'][0]-68.5075,f['anchor'][1]-5.348]
  if index==14:f['anchor'][1]=1035
  if index==15:f['anchor'][1]=1031
 return f
def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1')
 assert not any((out/name).exists() for name in ['sampling_submission.json','original.json','config_initial.json']),'Preserve attempted or refined sources; use their saved configs instead of resetting preparation'
 out.mkdir(exist_ok=True)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[16,2,3,4],[[30,1],[60,2],[90,3]],0,'One complete reciprocal swimming cycle IN PLACE. Tail peduncle flexes, paired flukes sweep up then down and the TWO pectoral fins stroke back then forward naturally, near and far fins remaining distinct. Torso rocks gently without horizontal root travel. Attached chains and five bells swing behind the swimming impulse without disconnecting. Return smoothly to the exact initial hovering ready pose. ',2026108301)
 recipe('attack',[16,5,6],[[32,1],[65,2]],0,'One physical body bash SCREEN RIGHT: draw the torso and head slightly backward, tuck the two pectoral fins, then lean and thrust the intact rounded head/shoulder forward once to contact. Original closed mouth stays closed. Recover the body and spread the same two fins back to exact hovering ready. Small anchored lunge only, no detached projectile, magic orb, bite, body swelling or repeated hits. ',2026108302)
 recipe('ranged',[16,8,9,10,11],[[25,1],[50,2],[74,3],[96,4]],0,'One ranged Mourning Sonar broadside SCREEN RIGHT: inflate the throat slightly and angle the intact head forward, open the original mouth once to sound a restrained pale teal pulse at the mouth, then close the mouth, recoil gently and recover to exact hovering ready. The game supplies travelling projectile flight, so no detached projectile, expanding cloud or beam. Both original fins, all attached bells and the two tail flukes remain present. ',2026108303)
 recipe('hit',[16,12],[[48,1]],0,'One brief impact recoil: head and torso flinch backward, near and far pectoral fins fold closer to the belly, tail flukes lag and all attached bells swing forward once. Body stays hovering, intact and right-facing. Recover smoothly to exact ready without falling, turning away or growing new appendages. ',2026108304)
 recipe('defend',[16,7],[],1,'One continuous defensive brace. Bow the head slightly, tuck the near and far pectoral fins into the supplied compact guard, angle the paired flukes to counterbalance. Stay hovering at the original body height with every bell attached. Hold the compact guard for the final second, no return to ready, shield or new props. ',2026108305)
 recipe('cast',[16,1,19],[[40,1],[76,2]],0,'One distinct supportive mourning salutation. Slowly lift the intact head, draw both pectoral fins inward toward the chest and bow the head as the attached original bells swing gently together, then spread the same fins and lower the head back into exact hovering ready. This is a restrained close-body support gesture with no mouth emission, projectile, magic cloud or new bell. The original whale remains one coherent animal. ',2026108306)
 recipe('death',[16,13,14,15],[[40,1],[78,2]],3,'One continuous gravity-driven collapse. Swimming stops, the entire intact whale sinks, rolls gently onto its near side and lands belly/fin side on the fixed ground plane into the supplied original corpse. The two pectoral fins fold and paired tail flukes settle, attached bells and chains fall naturally beside the body without detaching or disappearing. No shrinking, swimming away, melting, new fins or standing back up. End with closed eye and mouth, body fully grounded and last second motionless. ',2026108307)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='All24 original poses inspected chronologically and curated identity enlarged. Existing idle16-23 visibly articulates two pectoral fins, paired tail flukes and bell sway, preserving exact8 pixels and200ms. Seven H3 actions require full original RGB/enlarged alpha/native/reflected/live review.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,640],ground_anchor=[480,576],ready_guide=reference(16),corpse_guide=reference(15),original_source_registration=dict(near_fin_joint_old=[230,177],near_fin_joint_idle=[245,312],old_source_scale=.8,idle_source_scale=.7322,old_master_anchor_adjustment=[-68.5075,-5.348],corpse_anatomical_body_contact_y=1031),reason='Original scale per master retained; one master-wide torso/fin-joint registration aligns original ready to accepted idle. Death endpoint uses reviewed actual ventral body contact instead of floating original anchor. No per-frame bbox normalization, warping or motion synthesis.'))
